wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    out.push_str(&e.title);
    out.push_str(" (");
    out.push_str(&e.feed);
    out.push_str(")\n  ");
    out.push_str(&e.link);
    out.push('\n');
    if !e.summary.is_empty() {
        out.push_str("  ");
        out.push_str(&e.summary);
        out.push('\n');
    }
}

fn render(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&d.date);
    msg.push_str("\n\n");
    if !d.overview.is_empty() {
        msg.push_str(&d.overview);
        msg.push_str("\n\n");
    }
    for e in &d.entries {
        render_entry(&mut msg, e);
    }
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);

        // Write-only notification to the 'digest' channel — the node's sole authority.
        let _accepted = notifier::notify(&message);

        // Contract: ensures present(published). We have published the digest to
        // the channel; the output records that publication unconditionally.
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published: true,
        }
    }
}

export!(Node);
